package com.semes.reqops.domain.migration.service;
import lombok.RequiredArgsConstructor; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import java.util.*;
@Service @RequiredArgsConstructor public class MigrationVerifier {private final JdbcTemplate jdbc;public Map<String,Long> verify(){Map<String,Long> out=new LinkedHashMap<>();out.put("orphanIssues",jdbc.queryForObject("select count(*) from dev_issues i where not exists(select 1 from requirements r where r.id=i.requirement_id)",Long.class));out.put("orphanArtifacts",jdbc.queryForObject("select count(*) from dev_issue_artifacts a where not exists(select 1 from dev_issues i where i.id=a.dev_issue_id)",Long.class));out.put("invalidArtifactJson",jdbc.queryForObject("select count(*) from dev_issue_artifacts where content_json is not json",Long.class));return out;}}
